const getCorrectionCutoff = `-- name: GetCorrectionCutoff :one
WITH source_revision AS (
    SELECT source.created_at
    FROM official_result_revisions AS source
    WHERE source.id = $4
        AND source.tournament_id = $3
        AND source.roster_id = $1
        AND source.series_id = $2
)
SELECT CASE
    WHEN tournament.state IN ('completed', 'cancelled')
        THEN 'tournament_terminal'
    WHEN EXISTS (
        SELECT 1
        FROM waves AS wave
        CROSS JOIN source_revision AS source
        WHERE wave.tournament_id = tournament.id
            AND wave.roster_id = $1
            AND wave.started_at > source.created_at
    ) THEN 'wave_started'
    WHEN EXISTS (
        SELECT 1
        FROM task_delivery_receipts AS receipt
        INNER JOIN assignments AS assignment
            ON assignment.id = receipt.assignment_id
        CROSS JOIN source_revision AS source
        WHERE assignment.series_id = $2
            AND receipt.delivered_at > source.created_at
    ) THEN 'task_delivered'
    WHEN EXISTS (
        SELECT 1
        FROM result_events AS result_event
        CROSS JOIN source_revision AS source
        WHERE result_event.tournament_id = tournament.id
            AND result_event.roster_id = $1
            AND result_event.series_id = $2
            AND result_event.result_reason IN ('no_show', 'operator_forfeit')
            AND result_event.occurred_at > source.created_at
    ) THEN 'no_show_or_forfeit'
    WHEN EXISTS (
        SELECT 1
        FROM golden_memberships AS membership
        CROSS JOIN source_revision AS source
        WHERE membership.tournament_id = tournament.id
            AND membership.roster_id = $1
            AND membership.selection_kind = 'direct'
            AND membership.selected_at > source.created_at
    ) THEN 'golden_direct_allocated'
    ELSE ''::TEXT
END AS cutoff_code
FROM tournaments AS tournament
WHERE tournament.id = $3
`

type GetCorrectionCutoffParams struct {
	RosterID         uuid.UUID
	SeriesID         uuid.UUID
	TournamentID     uuid.UUID
	SourceRevisionID uuid.UUID
}

func (q *Queries) GetCorrectionCutoff(ctx context.Context, arg GetCorrectionCutoffParams) (string, error) {
	row := q.db.QueryRow(ctx, getCorrectionCutoff,
		arg.RosterID,
		arg.SeriesID,
		arg.TournamentID,
		arg.SourceRevisionID,
	)
	var cutoff_code string
	err := row.Scan(&cutoff_code)
	return cutoff_code, err
}

